code_examples.text:
when HTTP_REQUEST {
  if { [HTTP::uri] ends_with ".gif" } {
     node 10.1.2.200 80
  }
}
when LB_FAILED {
  log local0. "Selected server [LB::server] did not respond. Re-selecting node from myPool"
  pool myPool
  LB::reselect
}

when HTTP_REQUEST {
 if { [HTTP::uri] ends_with ".gif" } {
     node "10.1.2.200:80"
  }
}

when LB_FAILED {
  log local0. "Selected server [LB::server] did not respond. Re-selecting node from myPool"
  pool myPool
  LB::reselect
}
